system_ &lt;- Sys.info()[["sysname"]]


get_linux_os &lt;- function(key) {
  if (!file.exists("/etc/os-release")) {
    return(NA_character_)
  }
  x &lt;- grep(paste0("^", key, "="), readLines("/etc/os-release"), value = TRUE)[1]
  if (is.na(x)) {
    return(NA_character_)
  }
  value &lt;- gsub('^"|"$', "", sub(paste0("^", "PRETTY_NAME", "="), "", x))
  if (grepl("Void Linux", value)) value &lt;- paste0(value, " btw.")
  value
}
proc_value &lt;- function(path, key) {
  if (!file.exists(path)) {
    return(NA_character_)
  }
  x &lt;- grep(key, readLines(path), value = TRUE)[1]
  if (is.na(x)) {
    return(NA_character_)
  }
  trimws(sub("^[^:]*:", "", x))
}

if (system_ == "Darwin") {
  cpu_name &lt;- system("sysctl -n machdep.cpu.brand_string", intern = TRUE)
} else {
  cpu_name &lt;- proc_value("/proc/cpuinfo", "model name")
}

library(ps)
env_stats &lt;- data.frame(
  item = c(
    "OS", "Kernel", "CPU", "Cores (physical)", "Cores (logical)",
    "Memory", "R", "BLAS", "Python"
  ),
  value = c(
    if (system_ == "Linux") get_linux_os("PRETTY_NAME") else system_,
    paste(Sys.info()[["sysname"]], Sys.info()[["release"]], Sys.info()[["machine"]]),
    cpu_name,
    parallel::detectCores(logical = FALSE),
    parallel::detectCores(logical = TRUE),
    sprintf("%.1f GiB", ps_system_memory()$total / 1e9),
    R.version.string,
    unname(extSoftVersion()["BLAS"]),
    sub(" .*", "", reticulate::py_config()$version_string)
  )
)
knitr::kable(env_stats, col.names = c("", ""), row.names = FALSE)









